"""Configuration loader for mini_harness: JSON and minimal YAML."""

import json
import re
from pathlib import Path


DEFAULT_CONFIG_NAMES = ("config.yaml", "config.yml", "config.json")
DEFAULT_CONFIG = {
    "max_retries": 2,
    "log_dir": "logs",
}


class ConfigError(Exception):
    """Raised when config file cannot be parsed."""


# ----- minimal YAML parser (std lib only) -----

def _parse_yaml(text):
    """Parse a minimal YAML subset: scalars, sequences, mappings, comments."""
    lines = text.splitlines()
    root = {}
    ctx = [(root, -1, None)]
    current_seq = None

    for lineno, raw in enumerate(lines, 1):
        stripped = raw.rstrip()
        if not stripped or stripped.lstrip().startswith("#"):
            continue

        indent = len(raw) - len(raw.lstrip())
        line = stripped

        # pop context to current indent level
        while ctx and indent <= ctx[-1][1]:
            _resolve_pending(ctx)
            ctx.pop()
            current_seq = None

        if not ctx:
            ctx = [(root, -1, None)]

        parent, _, pending_key = ctx[-1]

        # sequence item: "- value"
        if line.lstrip().startswith("- "):
            seq_val = line.lstrip()[2:].strip()
            if pending_key is not None:
                _resolve_pending_as_list(ctx)
                parent = ctx[-1][0]
                current_seq = parent
            if current_seq is None:
                raise ConfigError(f"Line {lineno}: sequence item outside mapping key")
            if seq_val == "":
                child = {}
                current_seq.append(child)
                ctx.append((child, indent, None))
            else:
                current_seq.append(_parse_yaml_scalar(seq_val))
            continue

        # mapping key: "key: value" or "key:"
        m = re.match(r"^([^:]+?):(?:\s+(.*))?$", line)
        if not m:
            raise ConfigError(f"Line {lineno}: invalid YAML line: {line!r}")

        key = m.group(1).strip()
        raw_val = (m.group(2) or "").strip()

        _resolve_pending(ctx)

        if isinstance(parent, list):
            raise ConfigError(f"Line {lineno}: cannot nest mapping key under sequence")

        if raw_val == "":
            ctx.append((parent, indent, key))
            current_seq = None
        elif raw_val == "[]":
            parent[key] = []
            current_seq = parent[key]
            ctx.append((parent, indent, None))
        else:
            parent[key] = _parse_yaml_scalar(raw_val)
            current_seq = None

    for _ in range(len(ctx)):
        _resolve_pending(ctx)

    return root


def _resolve_pending(ctx):
    """If the top of stack has a pending key, resolve it as an empty mapping."""
    if ctx and ctx[-1][2] is not None:
        parent, indent, key = ctx[-1]
        ctx[-1] = (parent, indent, None)
        parent[key] = {}


def _resolve_pending_as_list(ctx):
    """Convert the top-of-stack pending key to a list."""
    if ctx and ctx[-1][2] is not None:
        parent, indent, key = ctx[-1]
        lst = []
        parent[key] = lst
        ctx[-1] = (lst, indent, None)


def _parse_yaml_scalar(s):
    """Parse a YAML scalar: null, bool, int, float, string."""
    s = s.strip()
    if s in ("null", "~", ""):
        return None
    if s in ("true", "True", "TRUE"):
        return True
    if s in ("false", "False", "FALSE"):
        return False
    try:
        if "." in s or "e" in s.lower():
            return float(s)
        return int(s)
    except ValueError:
        pass
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    return s


# ----- public API -----

def find_config(repo_root, explicit_path=None):
    """Resolve config path: explicit > defaults in repo_root."""
    root = Path(repo_root)
    if explicit_path:
        p = Path(explicit_path)
        if not p.is_absolute():
            p = root / p
        if p.exists():
            return p
        return None
    for name in DEFAULT_CONFIG_NAMES:
        p = root / name
        if p.exists():
            return p
    return None


def load_config(repo_root, explicit_path=None):
    """Load configuration, merging with defaults.

    Returns a dict with at least: max_retries, log_dir.
    """
    cfg = dict(DEFAULT_CONFIG)
    path = find_config(repo_root, explicit_path)
    if path is None:
        return cfg

    text = path.read_text(encoding="utf-8")
    # strip BOM if present
    if text and text[0] == "\ufeff":
        text = text[1:]

    if path.suffix in (".yaml", ".yml"):
        parsed = _parse_yaml(text)
    else:
        parsed = json.loads(text)

    if not isinstance(parsed, dict):
        raise ConfigError(f"Config must be a mapping, got {type(parsed).__name__}")

    for k, v in parsed.items():
        if k in DEFAULT_CONFIG or k in ("inputs", "output"):
            cfg[k] = v
        elif k == "sources":
            cfg.setdefault("inputs", v)
    return cfg


def resolve_path(repo_root, p):
    """Return absolute path: if relative, join with repo_root."""
    p = Path(p)
    if p.is_absolute():
        return str(p)
    return str(Path(repo_root) / p)

"""DAG runner: extract -> clean -> report, with retry and logging."""
import csv
import json
import logging
import re
from pathlib import Path


class HarnessError(Exception):
    """Raised for harness-level failures."""


def _to_snake_case(name):
    s1 = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", name)
    s2 = re.sub(r"([a-z\d])([A-Z])", r"\1_\2", s1)
    s3 = re.sub(r"[-\s]+", "_", s2)
    return s3.lower().strip("_")


def _extract_csv(path):
    records = []
    with open(path, newline="", encoding="utf-8") as f:
        lines = []
        for line in f:
            if not line.lstrip().startswith("#"):
                lines.append(line)
        reader = csv.DictReader(lines)
        for row in reader:
            records.append({k: v for k, v in row.items() if k is not None})
    return records


def _extract_jsonl(path):
    records = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def _extract(inputs):
    all_records = []
    for path in inputs:
        p = Path(path)
        if p.suffix == ".csv":
            all_records.extend(_extract_csv(str(p)))
        elif p.suffix == ".jsonl":
            all_records.extend(_extract_jsonl(str(p)))
        else:
            raise HarnessError(f"Unsupported file type: {path}")
    return all_records


def _clean(records):
    processed = []
    rejects = []
    for rec in records:
        if all(v is None or str(v).strip() == "" for v in rec.values()):
            continue
        cleaned = {_to_snake_case(k): v for k, v in rec.items()}
        if "id" not in cleaned or cleaned["id"] is None or str(cleaned["id"]).strip() == "":
            rejects.append(cleaned)
        else:
            processed.append(cleaned)
    return processed, rejects


def _report(processed, rejects, retry_count, source_files, output_path, repo_root=None):
    report = {
        "processed_count": len(processed),
        "rejected_count": len(rejects),
        "retry_count": retry_count,
        "source_files": source_files,
        "memory_summary": "memory/memory_summary.md",
    }
    out = Path(output_path)
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)
    return report


def _setup_logging(log_dir):
    log_dir = Path(log_dir)
    log_dir.mkdir(parents=True, exist_ok=True)
    log_path = log_dir / "dag.log"
    logger = logging.getLogger("mini_harness")
    logger.setLevel(logging.DEBUG)
    logger.handlers.clear()
    fh = logging.FileHandler(str(log_path), encoding="utf-8")
    fh.setLevel(logging.DEBUG)
    fh.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s"))
    logger.addHandler(fh)
    return logger


def run_dag(inputs, output, repo_root=None, max_retries=2, log_dir=None):
    if repo_root is None:
        repo_root = str(Path(__file__).resolve().parent.parent)
    repo = Path(repo_root)

    if log_dir is None:
        log_dir = str(repo / "logs")

    logger = _setup_logging(log_dir)
    total_retries = 0

    raw_records = None
    processed = None
    rejects = None

    for stage_name in ("extract", "clean", "report"):
        attempt = 1
        last_error = None

        while attempt <= max_retries + 1:
            try:
                if stage_name == "extract":
                    raw_records = _extract(inputs)
                elif stage_name == "clean":
                    if raw_records is None:
                        raise HarnessError("extract must run before clean")
                    processed, rejects = _clean(raw_records)
                elif stage_name == "report":
                    if processed is None:
                        raise HarnessError("clean must run before report")
                    _report(processed, rejects, total_retries, inputs, output, repo_root=str(repo))
                    logger.info("attempt=%d stage=%s status=ok", attempt, stage_name)
                    return output

                logger.info("attempt=%d stage=%s status=ok", attempt, stage_name)
                break
            except Exception as e:
                last_error = e
                if attempt <= max_retries:
                    logger.warning(
                        "attempt=%d stage=%s status=retry error=%s",
                        attempt, stage_name, e,
                    )
                else:
                    logger.error(
                        "attempt=%d stage=%s status=fail error=%s",
                        attempt, stage_name, e,
                    )
                attempt += 1
                total_retries += 1
        else:
            raise HarnessError(
                f"Stage '{stage_name}' failed after {max_retries} retries: {last_error}"
            )

    return None

